const mapStateToProps = (state) => {
	return {
		fileSets       : state.fileSets,
		deleteItem     : state.fileSets.deleteItem,
		deleteStatus   : state.fileSets.deleteStatus,
		deleteItemName : state.fileSets.deleteItemName,
	};
};

const mapDispatchToProps = (dispatch) => {
	return bindActionCreators(
		{
			fetchAllAdvisements,
			fetchVisaSummary,
			fetchVisaAcquirer,
			fetchVisaIssuer,
			fetchAllVss,
			fetchVisaPostingOverview,
			deleteAcquirerPostingSummaryItem,
			deleteIssuerPostingSummaryItem,
			deleteVisaPostingSummaryItem,
			confirmDelete,
			confirmDeleteIssuer,
			confirmDeleteAcquirer,
			cancelDeleteFunc,
		},
		dispatch,
	);
};

export default connect(mapStateToProps, mapDispatchToProps)(VisaSettlement);
