import React from "react";
import { Button, Modal, ModalHeader, ModalBody, ModalFooter } from "reactstrap";

const VisaPostingModal = ({
	confirmDelete,
	confirmDeleteIssuer,
	confirmDeleteAcquirer,
	className,
	cancelDelete,
	showModal,
	deleteItem,
	deleteItemName,
}) => {
	const handleDeleteSummary = (itemName, confirmDelete, confirmDeleteIssuer, confirmDeleteAcquirer) => {
		// selective call action creator depending on where they where clicked on in VisaSettlement.js
		if (itemName === "combineSummary") {
			return confirmDelete;
		}

		if (itemName === "issuer") {
			return confirmDeleteIssuer;
		}

		if (itemName === "acquirer") {
			return confirmDeleteAcquirer;
		}
	};
	return (
		<Modal isOpen={showModal} className={className}>
			<ModalHeader className='d-flex justify-content-center align-items-center'>
				<p style={{ fontSize: "1rem" }}>
					<strong>Confirm Action!</strong>
				</p>
			</ModalHeader>
			<ModalBody>
				<h4 className='text-primary text-center'>
					<strong>Are you sure you want to delete:</strong>
				</h4>
				<p className='text-center text-danger'>{deleteItem && deleteItem.filename}?</p>
				<p className='text-center text-primary'>Click yes to confirm or Cancel to cancel action!</p>
			</ModalBody>
			<ModalFooter>
				<Button
					color='danger'
					onClick={// choose which delete action creator to call depending on where it was clicked in VisaSettlement.js viz: issuer, acquirer or combine summary!
					handleDeleteSummary(deleteItemName, confirmDelete, confirmDeleteIssuer, confirmDeleteAcquirer)}
				>
					Yes
				</Button>{" "}
				<Button color='secondary' onClick={cancelDelete}>
					Cancel
				</Button>
			</ModalFooter>
		</Modal>
	);
};

export default VisaPostingModal;
